#include "stm32g4xx.h"

int main(void) {
    /* 1. Enable peripheral clocks for GPIOA and TIM1 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PA8 as Alternate Function AF6 (TIM1_CH1) */
    /* Select AF6 on PA8 via AFR[1] (AFRH bits 3:0) */
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(0xFU << GPIO_AFRH_AFSEL8_Pos)) | (6U << GPIO_AFRH_AFSEL8_Pos);
    /* Set PA8 mode to Alternate Function (MODER = 10b) */
    GPIOA->MODER = (GPIOA->MODER & ~(3U << GPIO_MODER_MODE8_Pos)) | (2U << GPIO_MODER_MODE8_Pos);
    /* Set very high output speed */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);

    /* 3. Configure TIM1 time-base:
     *    TIM1 counter clock = 170 MHz / (PSC + 1) = 170 MHz / (0 + 1) = 170 MHz.
     *    PWM frequency = 170 MHz / ((PSC + 1) * (ARR + 1)) = 170 MHz / (1 * 8500) = 20,000 Hz (20 kHz).
     */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;

    /* 4. Configure Channel 1 for 25% duty cycle:
     *    CCR1 = 8500 * 25% = 2125.
     */
    TIM1->CCR1 = 2125;

    /* 5. Configure Channel 1 PWM Mode 1 (active while CNT < CCR1) and enable output preload */
    TIM1->CCMR1 = (TIM1->CCMR1 & ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk)) |
                  (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 6. Enable Channel 1 output on pin (active-high polarity by default: CC1P = 0) */
    TIM1->CCER |= TIM_CCER_CC1E;

    /* 7. Enable Main Output (MOE bit in BDTR), required for TIM1 advanced-control timer */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 8. Enable auto-reload preload (ARPE), start the counter (CEN), and trigger update event */
    TIM1->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;
    TIM1->EGR |= TIM_EGR_UG;

    while (1) {
    }
}
```

### Explanation

1. **Clock Enable**: The GPIOA clock is enabled in `RCC->AHB2ENR` (`RCC_AHB2ENR_GPIOAEN`) and the TIM1 peripheral clock is enabled in `RCC->APB2ENR` (`RCC_APB2ENR_TIM1EN`).
2. **GPIO Configuration**: Pin PA8 is mapped to Alternate Function AF6 (`TIM1_CH1`) by configuring `GPIOA->AFR[1]` (bits [3:0] corresponding to pin 8) and setting `GPIOA->MODER` to alternate function mode (`10b`). High output speed is selected via `GPIOA->OSPEEDR`.
3. **Frequency & Period Calculation**:
   - Given `TIM1CLK = 170 MHz` (APB2 prescaler = 1), setting `TIM1->PSC = 0` provides a timer tick frequency of 170 MHz.
   - For a target frequency of $20\text{ kHz}$, the total period in counter counts is:
     $$\text{ARR} + 1 = \frac{170{,}000{,}000\text{ Hz}}{20{,}000\text{ Hz}} = 8500 \implies \text{ARR} = 8499$$
     This results in an exact 20 kHz PWM output (0% frequency error).
4. **Duty Cycle Calculation**:
   - For a 25% duty cycle in edge-aligned upcounting PWM mode 1:
     $$\text{CCR1} = 8500 \times 0.25 = 2125$$
     This provides exactly 25.0% duty cycle (0% error).
5. **Channel Output & PWM Mode**:
   - In `TIM1->CCMR1`, Channel 1 is configured as output (`CC1S = 00b`), PWM Mode 1 (`OC1M = 0110b`), and output compare preload is enabled (`OC1PE`).
   - In `TIM1->CCER`, `CC1E` is asserted to connect the output signal to the pin. Active-high polarity is maintained with `CC1P = 0`.
6. **Main Output Enable (MOE)**: Because TIM1 is an advanced-control timer with break/dead-time capabilities, setting `TIM1->BDTR |= TIM_BDTR_MOE` is mandatory to output PWM on the physical pins.
7. **Counter Activation**: The auto-reload preload (`ARPE`) and counter enable (`CEN`) bits are set in `TIM1->CR1`, and `TIM1->EGR |= TIM_EGR_UG` is asserted to generate an update event and immediately load the shadow registers.

