#include "stm32g4xx.h"

int main(void) {
    /* 1. Enable GPIOA and GPIOC peripheral clocks on AHB2 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOCEN;

    /* 2. Configure I2C3 kernel clock source to SYSCLK (170 MHz)
     *    RCC_CCIPR: I2C3SEL[1:0] = 01b (System clock selected as I2C3 clock)
     */
    RCC->CCIPR = (RCC->CCIPR & ~RCC_CCIPR_I2C3SEL) | RCC_CCIPR_I2C3SEL_0;

    /* 3. Enable I2C3 peripheral clock on APB1 */
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* 4. Configure GPIO pins:
     *    - PA8: Alternate Function AF2 (I2C3_SCL), Open-Drain, High Speed, Pull-up
     *    - PC9: Alternate Function AF8 (I2C3_SDA), Open-Drain, High Speed, Pull-up
     */
    /* PA8 configuration */
    GPIOA->MODER = (GPIOA->MODER & ~GPIO_MODER_MODE8) | (2U << GPIO_MODER_MODE8_Pos);
    GPIOA->OTYPER |= GPIO_OTYPER_OT8;                                   /* Open-drain */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);                 /* High speed */
    GPIOA->PUPDR = (GPIOA->PUPDR & ~GPIO_PUPDR_PUPD8) | (1U << GPIO_PUPDR_PUPD8_Pos); /* Pull-up */
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(0xFU << ((8U - 8U) * 4U))) | (2U << ((8U - 8U) * 4U)); /* AF2 */

    /* PC9 configuration */
    GPIOC->MODER = (GPIOC->MODER & ~GPIO_MODER_MODE9) | (2U << GPIO_MODER_MODE9_Pos);
    GPIOC->OTYPER |= GPIO_OTYPER_OT9;                                   /* Open-drain */
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED9_Pos);                 /* High speed */
    GPIOC->PUPDR = (GPIOC->PUPDR & ~GPIO_PUPDR_PUPD9) | (1U << GPIO_PUPDR_PUPD9_Pos); /* Pull-up */
    GPIOC->AFR[1] = (GPIOC->AFR[1] & ~(0xFU << ((9U - 8U) * 4U))) | (8U << ((9U - 8U) * 4U)); /* AF8 */

    /* 5. Configure I2C3 timing:
     *    Disable peripheral before programming I2C3_TIMINGR (PE = 0)
     */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /* Timing calculation for fI2CCLK = 170 MHz:
     * - PRESC = 15
     * - SCLDEL = 4
     * - SDADEL = 2
     * - SCLH = 48
     * - SCLL = 51
     */
    I2C3->TIMINGR = (15U << I2C_TIMINGR_PRESC_Pos) |
