    /* 1. Select HSI16 (16 MHz) as the I2C3 kernel clock source */
    RCC->CCIPR &= ~RCC_CCIPR_I2C3SEL_Msk;
    RCC->CCIPR |= (2U << RCC_CCIPR_I2C3SEL_Pos);

    /* 2. Enable clocks for GPIOC and I2C3 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* 3. Configure PC8 (I2C3_SCL) and PC9 (I2C3_SDA) */
    /* Mode: Alternate Function (10b) */
    GPIOC->MODER &= ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk);
    GPIOC->MODER |= (GPIO_MODER_MODE8_1 | GPIO_MODER_MODE9_1);

    /* Output type: Open-Drain (1b) */
    GPIOC->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);

    /* Output speed: Very High Speed (11b) */
    GPIOC->OSPEEDR |= (GPIO_OSPEEDR_OSPEED8_Msk | GPIO_OSPEEDR_OSPEED9_Msk);

    /* Pull-up: enable internal pull-up (01b) */
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk);
    GPIOC->PUPDR |= (GPIO_PUPDR_PUPD8_0 | GPIO_PUPDR_PUPD9_0);

    /* Select AF8 (I2C3) on PC8 and PC9 (AFRH register) */
    GPIOC->AFR[1] &= ~(GPIO_AFRH_AFSEL8_Msk | GPIO_AFRH_AFSEL9_Msk);
    GPIOC->AFR[1] |= ((8U << GPIO_AFRH_AFSEL8_Pos) | (8U << GPIO_AFRH_AFSEL9_Pos));

    /* 4. Configure I2C3: Ensure PE = 0 before writing TIMINGR */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /* Standard-mode (100 kHz) timing for 16 MHz kernel clock:
     * PRESC = 3, SCLDEL = 4, SDADEL = 2, SCLH = 0x0F, SCLL = 0x13 */
    I2C3->TIMINGR = (3U << 28) | (4U << 20) | (2U << 16) | (0x0FU << 8) | (0x13U << 0);

    /* 5. Enable I2C3 peripheral */
    I2C3->CR1 |= I2C_CR1_PE;
}
