#include "stm32g4xx.h"

void i2c3_master_init(void)
{
    /* 1. Select HSI16 (16 MHz) as I2C3 kernel clock source in RCC->CCIPR */
    /* CCIPR bits [17:16] (I2C3SEL): 10b = HSI16 clock selected */
    RCC->CCIPR &= ~RCC_CCIPR_I2C3SEL_Msk;
    RCC->CCIPR |= (2U << RCC_CCIPR_I2C3SEL_Pos);

    /* 2. Enable peripheral clocks for GPIOC and I2C3 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* 3. Configure PC8 (I2C3_SCL) and PC9 (I2C3_SDA) */
    /* Alternate function mode (10b) */
    GPIOC->MODER &= ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk);
    GPIOC->MODER |= ((2U << GPIO_MODER_MODE8_Pos) | (2U << GPIO_MODER_MODE9_Pos));

    /* Output type: Open-Drain (1b) */
    GPIOC->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);

    /* Output speed: Medium Speed (01b) */
    GPIOC->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED8_Msk | GPIO_OSPEEDR_OSPEED9_Msk);
    GPIOC->OSPEEDR |= ((1U << GPIO_OSPEEDR_OSPEED8_Pos) | (1U << GPIO_OSPEEDR_OSPEED9_Pos));

    /* Pull-up enabled (01b) */
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk);
    GPIOC->PUPDR |= ((1U << GPIO_PUPDR_PUPD8_Pos) | (1U << GPIO_PUPDR_PUPD9_Pos));

    /* Alternate function AF8 for PC8 and PC9 (AFRH: bits 3:0 for PC8, bits 7:4 for PC9) */
    GPIOC->AFR[1] &= ~((0xFU << ((8U - 8U) * 4U)) | (0xFU << ((9U - 8U) * 4U)));
    GPIOC->AFR[1] |= ((8U << ((8U - 8U) * 4U)) | (8U << ((9U - 8U) * 4U)));

    /* 4. Configure I2C3 peripheral for 100 kHz Standard Mode */
    /* Ensure peripheral is disabled (PE = 0) before writing TIMINGR */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /*
     * TIMINGR configuration for 16 MHz HSI16 clock:
     * PRESC  = 3   (divider = 4 -> tPRESC = 250 ns)
     * SCLDEL = 4   (data setup time = (4+1)*250 ns = 1250 ns)
     * SDADEL = 2   (data hold time  = 2*250 ns     = 500 ns)
     * SCLH   = 15  (high period     = (15+1)*250 ns = 4000 ns)
     * SCLL   = 19  (low period      = (19+1)*250 ns = 5000 ns)
     * Total period ~ 10 us (100 kHz)
     */
    I2C3->TIMINGR = (3U << I2C_TIMINGR_PRESC_Pos)
                  | (4U << I2C_TIMINGR_SCLDEL_Pos)
                  | (2U << I2C_TIMINGR_SDADEL_Pos)
                  | (15U << I2C_TIMINGR_SCLH_Pos)
                  | (19U << I2C_TIMINGR_SCLL_Pos);

    /* 5. Enable I2C3 peripheral */
    I2C3->CR1 |= I2C_CR1_PE;
}
