    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Enable Auto-reload preload (ARPE) */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* Output polarity active-high (CC1P = 0) and enable CH1 output (CC1E = 1) */
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER |= TIM_CCER_CC1E;

    /* Main Output Enable (BDTR MOE bit) - required for TIM1 outputs */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Force an update event (UG) to transfer PSC, ARR, and CCR1 to shadow registers */
    TIM1->EGR |= TIM_EGR_UG;

    /* Start the timer counter */
    TIM1->CR1 |= TIM_CR1_CEN;

    /* -------------------------------------------------------------
     * 4. I2C3 Configuration (100 kHz Standard Mode Controller)
     * ------------------------------------------------------------- */
    /* Disable I2C3 before writing TIMINGR */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /*
     * TIMINGR configuration for 16 MHz HSI16 kernel clock:
     * - PRESC  = 3  -> tPRESC = (3 + 1) * 62.5 ns = 250 ns
     * - SCLDEL = 4  -> Data setup time = (4 + 1) * 250 ns = 1250 ns
     * - SDADEL = 2  -> Data hold time  = 2 * 250 ns = 500 ns
     * - SCLH   = 15 -> SCL high period = (15 + 1) * 250 ns = 4000 ns
     * - SCLL   = 19 -> SCL low period  = (19 + 1) * 250 ns = 5000 ns
     */
    I2C3->TIMINGR = (3U << I2C_TIMINGR_PRESC_Pos)
                  | (4U << I2C_TIMINGR_SCLDEL_Pos)
                  | (2U << I2C_TIMINGR_SDADEL_Pos)
                  | (15U << I2C_TIMINGR_SCLH_Pos)
                  | (19U << I2C_TIMINGR_SCLL_Pos);

    /* Enable I2C3 peripheral */
    I2C3->CR1 |= I2C_CR1_PE;

    /* -------------------------------------------------------------
     * Main Loop
     * ------------------------------------------------------------- */
    while (1)
    {
        /* Background execution */
    }
}
```

