#include "stm32g4xx.h"

int main(void)
{
    /* =========================================================================
     * 1. Peripheral Clock Enable
     * ========================================================================= */
    /* Enable GPIOA and GPIOC clocks on AHB2 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOCEN;

    /* Enable I2C3 clock on APB1 */
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* Enable TIM1 clock on APB2 */
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* =========================================================================
     * 2. GPIO Pin Configuration
     * ========================================================================= */
    /* --- PA8: TIM1_CH1 (AF6, Push-Pull, Very High Speed) --- */
    GPIOA->MODER = (GPIOA->MODER & ~GPIO_MODER_MODE8_Msk) | (2U << GPIO_MODER_MODE8_Pos);
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(0xFU << GPIO_AFRH_AFSEL8_Pos)) | (6U << GPIO_AFRH_AFSEL8_Pos);

    /* --- PC8 (I2C3_SCL) & PC9 (I2C3_SDA): AF8, Open-Drain, Pull-Up, Very High Speed --- */
    GPIOC->MODER = (GPIOC->MODER & ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk))
                 | (2U << GPIO_MODER_MODE8_Pos)
                 | (2U << GPIO_MODER_MODE9_Pos);
    GPIOC->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);
    GPIOC->PUPDR = (GPIOC->PUPDR & ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk))
                 | (1U << GPIO_PUPDR_PUPD8_Pos)
                 | (1U << GPIO_PUPDR_PUPD9_Pos);
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos) | (3U << GPIO_OSPEEDR_OSPEED9_Pos);
    GPIOC->AFR[1] = (GPIOC->AFR[1] & ~(GPIO_AFRH_AFSEL8_Msk | GPIO_AFRH_AFSEL9_Msk))
                  | (8U << GPIO_AFRH_AFSEL8_Pos)
                  | (8U << GPIO_AFRH_AFSEL9_Pos);

    /* =========================================================================
     * 3. TIM1 Configuration (20 kHz, 25% Duty Cycle, Edge-Aligned PWM Mode 1)
     * ========================================================================= */
    /* Prescaler = 0 -> timer counter clock = 170 MHz */
    TIM1->PSC = 0U;

    /* Period: ARR = 8499 -> f_PWM = 170 MHz / (8499 + 1) = 20 kHz */
    TIM1->ARR = 8499U;

    /* Pulse width: CCR1 = 2125 -> Duty cycle = 2125 / 8500 = 25% */
    TIM1->CCR1 = 2125U;

    /* Channel 1 output compare configuration: PWM Mode 1, preload enabled */
    TIM1->CCMR1 = (TIM1->CCMR1 & ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk))
                | (6U << TIM_CCMR1_OC1M_Pos)
                | TIM_CCMR1_OC1PE;

    /* Enable Channel 1 output (active-high polarity by default: CC1P = 0) */
    TIM1->CCER |= TIM_CCER_CC1E;

    /* Enable auto-reload preload */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* Main Output Enable (required for advanced-control timer TIM1) */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Generate an update event to latch preloaded registers into shadow registers */
    TIM1->EGR |= TIM_EGR_UG;

    /* Start TIM1 counter */
    TIM1->CR1 |= TIM_CR1_CEN;

    /* =========================================================================
     * 4. I2C3 Configuration (Standard Mode 100 kHz Controller)
     * ========================================================================= */
    /* Ensure I2C3 is disabled before modifying TIMINGR */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /*
     * TIMINGR configuration for 100 kHz standard mode from 170 MHz PCLK1:
     * - PRESC  = 3   (divider = 4 -> t_PRESC = 23.53 ns)
     * - SCLDEL = 10  (t_SCLDEL = 258.8 ns >= 250 ns t_SU:DAT)
     * - SDADEL = 0   (t_SDADEL = 0 ns)
     * - SCLH   = 189 (t_SCLH = 4.47 us >= 4.0 us t_HIGH)
     * - SCLL   = 233 (t_SCLL = 5.51 us >= 4.7 us t_LOW)
     * Combined value: 0x30A0BDE9
     */
    I2C3->TIMINGR = 0x30A0BDE9U;

    /* Enable I2C3 peripheral */
    I2C3->CR1 |= I2C_CR1_PE;

    /* =========================================================================
     * 5. Infinite Background Loop
     * ========================================================================= */
    while (1)
    {
    }
}
```

---

### Explanation

1. **Clock Enabling**:
   - `RCC->AHB2ENR` enables `GPIOA` and `GPIOC` clock gating.
   - `RCC->APB1ENR1` enables the `I2C3` peripheral clock.
   - `RCC->APB2ENR` enables the `TIM1` peripheral clock.

2. **Pin Multiplexing & Pin Modes**:
   - **PA8** is configured in alternate function mode (`MODER8 = 10b`), push-pull output, very high speed, and assigned to **AF6** (`AFRH8 = 6`), mapping it to `TIM1_CH1`.
   - **PC8** (SCL) and **PC9** (SDA) are configured in alternate function mode (`MODER = 10b`), open-drain (`OTYPER`), with internal pull-ups enabled (`PUPDR`), and routed to **AF8** (`AFRH8 = 8`, `AFRH9 = 8`).
   - *Hardware Reminder*: Because the BME280 operates at 1.8 V I/O and the STM32G474 operates at 3.3 V ($V_{IH,\text{min}} = 2.31\text{ V}$), an external bidirectional open-drain level shifter (e.g. PCA9306) must be placed on the bus between the MCU and sensor.

3. **TIM1 PWM Setup (20 kHz, 25% Duty Cycle)**:
   - $f_{\text{TIM1\_CLK}} = 170\text{ MHz}$ (since APB2 prescaler is 1).
   - $\text{PSC} = 0$, $\text{ARR} = 8499$ produces exactly $\frac{170\text{ MHz}}{8500} = 20\text{ kHz}$.
   - $\text{CCR1} = 2125$ yields $\frac{2125}{8500} = 25.0\%$ duty cycle.
   - Channel 1 is configured in PWM Mode 1 (`OC1M = 0110b`) with output compare preload (`OC1PE = 1`).
   - Auto-reload preload is enabled (`ARPE = 1`), and the `UG` bit in `TIM1->EGR` latches preloaded settings.
   - Advanced timer output is enabled via `TIM1->BDTR |= TIM_BDTR_MOE`, and counting starts with `TIM1->CR1 |= TIM_CR1_CEN`.

4. **I2C3 Controller Setup (100 kHz Standard Mode)**:
   - `I2C3->CR1` is cleared of `PE` before writing `TIMINGR`.
