    TIM1->EGR |= TIM_EGR_UG;

    /* Start TIM1 counter */
    TIM1->CR1 |= TIM_CR1_CEN;

    /* =========================================================================
     * 4. I2C3 Configuration (Standard Mode 100 kHz Controller)
     * ========================================================================= */
    /* Ensure I2C3 is disabled before modifying TIMINGR */
    I2C3->CR1 &= ~I2C_CR1_PE;

