#include "stm32g4xx.h"

void SystemClock_Config_170MHz(void)
{
    /* 1. Enable power interface clock to configure power controller */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* 2. Switch main regulator to Range 1 Boost mode (SYSCLK > 150 MHz up to 170 MHz) */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 3. Configure Flash memory wait states:
     * In Range 1 Boost mode, 136 MHz < HCLK <= 170 MHz requires 4 WS (5 CPU cycles).
     */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS) {
        /* Wait for Flash latency to take effect */
    }

    /* 4. Configure PLL:
     * Source: HSI16 (16 MHz)
     * PLLM  : /4 (bitfield value 3) -> 4 MHz VCO input
     * PLLN  : *85                  -> 340 MHz VCO output
     * PLLR  : /2 (bitfield value 0) -> 170 MHz PLL_R output
     * PLLREN: Enable PLL 'R' output
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_1 |
                   (3U << RCC_PLLCFGR_PLLM_Pos) |
                   (85U << RCC_PLLCFGR_PLLN_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* 5. Enable the PLL and wait for PLLRDY */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
        /* Wait for PLL lock */
    }

    /* 6. Recommended transition sequence for switching to PLL with HCLK > 80 MHz:
     * Set AHB prescaler to /2 first, switch system clock to PLL, wait > 1 us,
     * then set AHB prescaler back to /1.
     */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV2;

    /* Switch SYSCLK source to PLL */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL) {
        /* Wait until PLL is used as system clock source */
    }

    /* Wait at least 1 us (approx. 20 iterations at 85 MHz) */
    for (__IO uint32_t i = 0; i < 50; i++) {
        __NOP();
    }

    /* Set AHB prescaler to /1 (SYSCLK not divided: HCLK = 170 MHz) */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV1;
    while ((RCC->CFGR & RCC_CFGR_HPRE) != RCC_CFGR_HPRE_DIV1) {
        /* Wait for prescaler update */
    }

    /* APB1 and APB2 prescalers remain at their reset value of /1 (PCLK1 = PCLK2 = 170 MHz) */
}
