### Complete Initialization Program (Clock Tree & PWM on PA8)

The following complete bare-metal C program configures:
1. **Clock Tree**: SYSCLK = HCLK = PCLK1 = PCLK2 = 170 MHz using HSI16 through the PLL in Range 1 Boost mode with 4 Flash wait states.
2. **PWM Output**: 20 kHz, 25 % duty cycle on PA8 (TIM1_CH1, Alternate Function AF6), active-high, edge-aligned PWM mode 1.

```c
#include "stm32g4xx.h"

int main(void)
{
    /* ------------------------------------------------------------------------
     * 1. Clock Configuration: SYSCLK = HCLK = PCLK1 = PCLK2 = 170 MHz
     * ------------------------------------------------------------------------ */

    /* Enable power interface clock to configure the power controller */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* Select Range 1 Boost mode (required for SYSCLK > 150 MHz up to 170 MHz) */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* Configure Flash latency: 4 WS (5 CPU cycles) required for 170 MHz in Boost mode */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS) {
        /* Wait for Flash latency to take effect */
    }

    /* Configure PLL:
     * Source: HSI16 (16 MHz)
     * PLLM  : /4 (field value 3) -> 4 MHz VCO input (valid range: 2.66 to 16 MHz)
     * PLLN  : *85                 -> 340 MHz VCO output (valid range: 96 to 344 MHz)
     * PLLR  : /2 (field value 0) -> 170 MHz system clock
     * PLLREN: Enable PLL 'R' clock output
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_1 |
                   (3U << RCC_PLLCFGR_PLLM_Pos) |
                   (85U << RCC_PLLCFGR_PLLN_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* Enable the main PLL and wait for PLLRDY */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
        /* Wait for PLL lock */
    }

    /* Safe frequency switching procedure (RM0440):
     * Set AHB prescaler to /2 first, switch system clock source to PLL,
     * wait > 1 us, then restore AHB prescaler to /1.
     */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV2;
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL) {
        /* Wait until PLL is the system clock source */
    }

    /* Wait > 1 us at intermediate clock (approx. 50 NOPs) */
    for (__IO uint32_t i = 0; i < 50; i++) {
        __NOP();
    }

    /* Set AHB prescaler back to /1: HCLK = SYSCLK = 170 MHz */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV1;
    while ((RCC->CFGR & RCC_CFGR_HPRE) != RCC_CFGR_HPRE_DIV1) {
        /* Wait for prescaler update */
    }

    /* ------------------------------------------------------------------------
     * 2. Peripheral Clock & GPIO Configuration for PA8 (TIM1_CH1)
     * ------------------------------------------------------------------------ */

    /* Enable GPIOA and TIM1 clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* Configure PA8: Alternate Function mode (MODER[17:16] = 10b) */
    GPIOA->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos);

    /* Assign AF6 (TIM1_CH1) to PA8 in AFRH (AFR[1], pin index 8) */
    GPIOA->AFR[1] &= ~(0xFU << ((8U - 8U) * 4U));
    GPIOA->AFR[1] |= (6U << ((8U - 8U) * 4U));

    /* Set high speed on PA8 */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);

    /* ------------------------------------------------------------------------
     * 3. TIM1 Configuration: 20 kHz PWM, 25 % Duty Cycle on Channel 1
     * ------------------------------------------------------------------------ */

    /* Timer clock = 170 MHz (APB2 prescaler = 1 -> TIM1CLK = 170 MHz)
     * Desired PWM frequency = 20,000 Hz:
     *   ARR = (TIM1CLK / ((PSC + 1) * f_target)) - 1
     *   With PSC = 0: ARR = (170,000,000 / (1 * 20,000)) - 1 = 8499
     * Duty cycle = 25 %:
     *   CCR1 = (ARR + 1) * 25% = 8500 * 0.25 = 2125
     */
    TIM1->PSC  = 0U;
    TIM1->ARR  = 8499U;
    TIM1->CCR1 = 2125U;

    /* Configure Channel 1:
     * - Output compare mode: PWM mode 1 (OC1M = 0110b)
     * - Enable preload register for CCR1 (OC1PE = 1)
     */
    TIM1->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Configure Channel 1 output polarity and enable:
     * - Active-high polarity: CC1P = 0
     * - Enable channel 1 output: CC1E = 1
     */
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER |= TIM_CCER_CC1E;

    /* Enable ARR preload register buffer (ARPE = 1) */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* Generate an update event to load preloaded registers into shadow registers */
    TIM1->EGR |= TIM_EGR_UG;

    /* TIM1 is an advanced timer: Main Output Enable (MOE) must be set in BDTR */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Enable counter */
    TIM1->CR1 |= TIM_CR1_CEN;

    /* Loop forever; PWM generation continues autonomously in hardware */
    while (1) {
    }
}
