#include "stm32g4xx.h"

void clock_init(void) {
    // 1. Enable PWR peripheral clock
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    // 2. Switch to Range 1 Boost mode (required for SYSCLK > 150 MHz)
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    // 3. Configure Flash memory access latency to 4 wait states (for 170 MHz in Range 1 Boost)
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;

    // 4. Configure PLL:
    //    Source: HSI16 (16 MHz)
    //    PLLM = /4 (value 3) -> 4 MHz VCO input (16 MHz / 4)
    //    PLLN = *85          -> 340 MHz VCO output (4 MHz * 85)
    //    PLLR = /2 (value 0) -> 170 MHz PLL 'R' output (340 MHz / 2)
    //    PLLREN = 1          -> Enable PLLR clock output to SYSCLK multiplexer
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_1 |
                   (3 << RCC_PLLCFGR_PLLM_Pos) |
                   (85 << RCC_PLLCFGR_PLLN_Pos) |
                   RCC_PLLCFGR_PLLREN;

    // 5. Enable the PLL and wait until it is locked
    RCC->CR |= RCC_CR_PLLON;
    while ((RCC->CR & RCC_CR_PLLRDY) == 0) {
        // Busy-wait until PLL is ready
    }

    // 6. Transition state (RM0440 p.233 & p.279):
    //    Divide HCLK by 2 first when switching to PLL with HCLK > 80 MHz
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV2;

    // 7. Select PLL as system clock source (SYSCLK)
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;

    // Wait until PLL is used as system clock
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL) {
        // Busy-wait for clock switch status
    }

    // 8. Wait at least 1 us in intermediate state
    for (volatile int i = 0; i < 100; i++) {
        __NOP();
    }

    // 9. Restore AHB prescaler to 1 (DIV1) to run HCLK at full 170 MHz
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV1;
}
