    }

    // Restore AHB prescaler to 1 (HCLK = 170 MHz)
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV1;

    // ------------------------------------------------------------------------
    // 2. GPIO Configuration: PA8 as TIM1_CH1 (AF6)
    // ------------------------------------------------------------------------

    // Enable clock gates for GPIOA and TIM1
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

