    GPIOA->MODER = (GPIOA->MODER & ~GPIO_MODER_MODE8) | GPIO_MODER_MODE8_1;

    // Map PA8 to Alternate Function 6 (TIM1_CH1) in AFR[1] (AFRH)
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(0xFu << GPIO_AFRH_AFSEL8_Pos)) |
                    (6u << GPIO_AFRH_AFSEL8_Pos);

    // ------------------------------------------------------------------------
    // 3. TIM1 Configuration: 20 kHz PWM, 25 % Duty Cycle on Channel 1
    // ------------------------------------------------------------------------

    // Timer clock = APB2 timer clock = 170 MHz
    // Target PWM frequency = 20 kHz -> Period = 50 us
    // With PSC = 0, ARR = (170 MHz / 20 kHz) - 1 = 8500 - 1 = 8499
    // For 25 % duty cycle: CCR1 = 8500 * 0.25 = 2125
    TIM1->PSC = 0;
    TIM1->ARR = 8499;
    TIM1->CCR1 = 2125;

    // Configure Channel 1 in PWM mode 1 (OC1M = 0110b), enable preload (OC1PE)
    TIM1->CCMR1 = (TIM1->CCMR1 & ~(TIM_CCMR1_OC1M | TIM_CCMR1_CC1S)) |
                  (6u << TIM_CCMR1_OC1M_Pos) |
                  TIM_CCMR1_OC1PE;

    // Enable Channel 1 output, active high (CC1E = 1, CC1P = 0)
    TIM1->CCER |= TIM_CCER_CC1E;

    // Enable Main Output Enable (MOE) bit in BDTR (required for TIM1 advanced timer)
    TIM1->BDTR |= TIM_BDTR_MOE;

    // Enable Auto-Reload Preload (ARPE) and start counter (CEN)
    TIM1->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;

    // ------------------------------------------------------------------------
    // Main loop
    // ------------------------------------------------------------------------
    while (1) {
    }
