```c
#include "stm32g4xx.h"

void buzzer_pwm_init(void)
{
    /* 1. Enable peripheral clocks */
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOAEN;     /* GPIOA clock */
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;     /* TIM3 clock (LED PWM) */
    RCC->APB2ENR  |= RCC_APB2ENR_TIM17EN;    /* TIM17 clock (Buzzer PWM) */

    /* ---------------------------------------------------------------------- */
    /* 2. Configure PA6 for Status LED (TIM3_CH1, AF2, 20 kHz, 40 % duty)    */
    /* ---------------------------------------------------------------------- */
    /* Set PA6 mode to Alternate Function (10b) */
    GPIOA->MODER &= ~GPIO_MODER_MODE6_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE6_Pos);

    /* Select AF2 (TIM3_CH1) for PA6 in AFRL */
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL6_Msk;
    GPIOA->AFR[0] |= (2U << GPIO_AFRL_AFSEL6_Pos);

    /* High speed output */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED6_Pos);

    /* TIM3 Timebase: f_tim = 170 MHz, f_pwm = 20 kHz -> PSC = 0, ARR = 8499 */
    TIM3->PSC = 0U;
    TIM3->ARR = 8499U;
    TIM3->CCR1 = 3400U;   /* 40 % duty cycle: 8500 * 0.40 = 3400 */

    /* PWM Mode 1 with preload enabled on Channel 1 */
    TIM3->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM3->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Enable output on CH1 (active-high polarity) */
    TIM3->CCER &= ~TIM_CCER_CC1P;
    TIM3->CCER |= TIM_CCER_CC1E;

    /* Enable ARPE, update registers, and start TIM3 */
    TIM3->CR1 |= TIM_CR1_ARPE;
    TIM3->EGR = TIM_EGR_UG;
    TIM3->CR1 |= TIM_CR1_CEN;

    /* ---------------------------------------------------------------------- */
    /* 3. Configure PA7 for Buzzer (TIM17_CH1, AF1, 1 kHz, 50 % duty)        */
    /* ---------------------------------------------------------------------- */
    /* Set PA7 mode to Alternate Function (10b) */
    GPIOA->MODER &= ~GPIO_MODER_MODE7_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE7_Pos);

    /* Select AF1 (TIM17_CH1) for PA7 in AFRL */
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL7_Msk;
    GPIOA->AFR[0] |= (1U << GPIO_AFRL_AFSEL7_Pos);

    /* High speed output */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED7_Pos);

    /* TIM17 Timebase: TIM17CLK = PCLK2 = 170 MHz                             */
    /* Target: 1 kHz PWM with 50 % duty                                      */
    /* Set PSC = 3 (counter clock = 170 MHz / 4 = 42.5 MHz)                  */
    /* ARR = (42.5 MHz / 1 kHz) - 1 = 42499                                  */
    /* CCR1 = (ARR + 1) * 0.50 = 42500 * 0.50 = 21250                        */
    TIM17->PSC = 3U;
    TIM17->ARR = 42499U;
    TIM17->CCR1 = 21250U;

    /* PWM Mode 1 (OC1M = 0110b) with preload enabled */
    TIM17->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM17->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Enable output on Channel 1 (active-high polarity) */
    TIM17->CCER &= ~TIM_CCER_CC1P;
    TIM17->CCER |= TIM_CCER_CC1E;

    /* TIM17 includes break/dead-time control: MOE bit must be set */
    TIM17->BDTR |= TIM_BDTR_MOE;

    /* Enable auto-reload preload, generate update event, and start TIM17 */
    TIM17->CR1 |= TIM_CR1_ARPE;
    TIM17->EGR = TIM_EGR_UG;
    TIM17->CR1 |= TIM_CR1_CEN;
}
