    GPIOA->MODER |= (2U << GPIO_MODER_MODE6_Pos) |
                    (2U << GPIO_MODER_MODE9_Pos) |
                    (2U << GPIO_MODER_MODE10_Pos);

    /* Output type: Push-Pull (0) on PA6 and PA9 */
    GPIOA->OTYPER &= ~(GPIO_OTYPER_OT6 | GPIO_OTYPER_OT9);

    /* Output speed: High Speed (0b11) on PA6, PA9, PA10 */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED6_Pos) |
                      (3U << GPIO_OSPEEDR_OSPEED9_Pos) |
                      (3U << GPIO_OSPEEDR_OSPEED10_Pos);

    /* Pull-up / pull-down: Enable pull-up (0b01) on PA10 (RX idle high) */
    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD6_Msk | GPIO_PUPDR_PUPD9_Msk | GPIO_PUPDR_PUPD10_Msk);
    GPIOA->PUPDR |= (1U << GPIO_PUPDR_PUPD10_Pos);

    /* Alternate Function registers:
     * - PA6  -> AF2 in AFRL (AFR[0])
     * - PA9  -> AF7 in AFRH (AFR[1])
     * - PA10 -> AF7 in AFRH (AFR[1])
     */
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL6_Msk;
    GPIOA->AFR[0] |= (2U << GPIO_AFRL_AFSEL6_Pos);

    GPIOA->AFR[1] &= ~(GPIO_AFRH_AFSEL9_Msk | GPIO_AFRH_AFSEL10_Msk);
    GPIOA->AFR[1] |= (7U << GPIO_AFRH_AFSEL9_Pos) | (7U << GPIO_AFRH_AFSEL10_Pos);

    /* 3. Configure USART1:
     *    - Kernel Clock = PCLK2 = 170000000 Hz
     *    - Target Baud Rate = 115200 bps
     *    - BRR = 170000000 / 115200 = 1476 (0x05C4) -> 115176 baud (0.02% error)
     *    - 8 data bits, no parity, 1 stop bit, oversampling by 16 (OVER8 = 0)
     *    - Transmitter and Receiver enabled
     */
    USART1->CR1 &= ~USART_CR1_UE; /* Ensure disabled before programming BRR */
    USART1->BRR = 1476U;
    USART1->CR2 &= ~USART_CR2_STOP_Msk; /* 1 Stop bit */
    USART1->CR1 &= ~(USART_CR1_M1 | USART_CR1_M0 | USART_CR1_PCE | USART_CR1_PS | USART_CR1_OVER8);
    USART1->CR1 |= USART_CR1_TE | USART_CR1_RE;
    USART1->CR1 |= USART_CR1_UE; /* Enable USART1 */

    /* 4. Configure TIM3 for 1 kHz PWM, 50% duty cycle on Channel 1 (PA6):
     *    - Timer Clock = PCLK1 = 170000000 Hz (APB1 prescaler is 1)
     *    - PWM frequency = 170000000 Hz / ((PSC + 1) * (ARR + 1))
     *                    = 170000000 Hz / ((3 + 1) * (42499 + 1)) = 1000 Hz
     *    - Duty cycle = CCR1 / (ARR + 1) = 21250 / 42500 = 50%
     */
    TIM3->PSC = 3U;
    TIM3->ARR = 42499U;
    TIM3->CCR1 = 21250U;

    /* Channel 1 Output Compare Mode: PWM mode 1 (OC1M = 0b0110), Preload enabled (OC1PE = 1) */
    TIM3->CCMR1 &= ~(TIM_CCMR1_CC1S_Msk | TIM_CCMR1_OC1M_Msk);
    TIM3->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Output polarity: active-high (CC1P = 0), Enable channel output (CC1E = 1) */
    TIM3->CCER &= ~TIM_CCER_CC1P;
    TIM3->CCER |= TIM_CCER_CC1E;

    /* Enable Auto-reload preload (ARPE) and Counter (CEN) */
    TIM3->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;

    /* Generate an update event (UG) to latch PSC, ARR, and CCR1 into active registers */
    TIM3->EGR |= TIM_EGR_UG;

    /* Main loop */
    while (1) {
        /* Application code runs here */
    }
}
