#include "stm32g4xx.h"

/**
 * @brief Initialize TIM3 Channel 1 on PA6 for a 1 kHz, 50% duty cycle PWM signal.
 *        - Timer clock: 170 MHz (APB1 prescaler = 1)
 *        - Mode: Edge-aligned PWM mode 1, active-high, no dead time
 */
void tim3_ch1_pwm_init(void)
{
    /* 1. Enable peripheral clock gates in RCC */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;        /* Enable GPIOA clock */
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;       /* Enable TIM3 clock */

    /* 2. Configure PA6 as Alternate Function 2 (TIM3_CH1) */
    /* MODER: Set PA6 to Alternate Function mode (0b10 = 2) */
    GPIOA->MODER &= ~GPIO_MODER_MODE6_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE6_Pos);

    /* OSPEEDR: Set PA6 to Very High Speed (0b11 = 3) */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED6_Pos);

    /* AFRL (AFR[0]): Set AF2 for PA6 (bits [27:24]) */
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL6_Msk;
    GPIOA->AFR[0] |= (2U << GPIO_AFRL_AFSEL6_Pos);

    /* 3. Configure TIM3 time base for 1 kHz */
    /* Prescaler: 170 MHz / (3 + 1) = 42.5 MHz counter clock */
    TIM3->PSC = 3U;

    /* Auto-reload: 42.5 MHz / (42499 + 1) = 1000 Hz PWM period */
    TIM3->ARR = 42499U;

    /* 50% duty cycle: CCR1 = 42500 / 2 = 21250 */
    TIM3->CCR1 = 21250U;

    /* 4. Configure Channel 1 for PWM Mode 1 with preload enabled */
    /* OC1M[3:0] = 0b0110 (PWM mode 1), OC1PE = 1 (preload enable), CC1S = 0b00 (output) */
    TIM3->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk);
    TIM3->CCMR1 |= (0x6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 5. Enable Channel 1 output with active-high polarity */
    TIM3->CCER &= ~(TIM_CCER_CC1P | TIM_CCER_CC1NP);
    TIM3->CCER |= TIM_CCER_CC1E;

    /* 6. Generate an update event to transfer PSC, ARR, and CCR1 to active shadow registers */
    TIM3->EGR |= TIM_EGR_UG;

    /* 7. Enable auto-reload preload (ARPE) and start the counter (CEN) */
    TIM3->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;
}
