    GPIOA->MODER &= ~(GPIO_MODER_MODE6_Msk | GPIO_MODER_MODE9_Msk | GPIO_MODER_MODE10_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE6_Pos) |
                    (2U << GPIO_MODER_MODE9_Pos) |
                    (2U << GPIO_MODER_MODE10_Pos);

    /* Set PA6, PA9, PA10 to Very High Speed (0b11 = 3) */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED6_Pos) |
                      (3U << GPIO_OSPEEDR_OSPEED9_Pos) |
                      (3U << GPIO_OSPEEDR_OSPEED10_Pos);

    /* AFR[0] (AFRL): Select AF2 for PA6 */
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL6_Msk;
    GPIOA->AFR[0] |= (2U << GPIO_AFRL_AFSEL6_Pos);

    /* AFR[1] (AFRH): Select AF7 for PA9 (TX) and PA10 (RX) */
    GPIOA->AFR[1] &= ~(GPIO_AFRH_AFSEL9_Msk | GPIO_AFRH_AFSEL10_Msk);
    GPIOA->AFR[1] |= (7U << GPIO_AFRH_AFSEL9_Pos) |
                     (7U << GPIO_AFRH_AFSEL10_Pos);

    /* -------------------------------------------------------------------------
     * 3. Configure USART1: 115200 baud, 8N1, oversampling by 16
     * -------------------------------------------------------------------------
     * Kernel clock = PCLK2 = 170 MHz.
     * BRR = 170000000 / 115200 = 1476 (0x5C4) -> 115176 baud (0.02% error).
     * Written before USART is enabled.
     */
    USART1->CR1 = 0U;   /* 8 data bits, no parity, OVER16 = 0, UE = 0 */
    USART1->CR2 = 0U;   /* 1 stop bit */
    USART1->CR3 = 0U;   /* No hardware flow control */
    USART1->BRR = 1476U;
