     * ARR = 42499   -> PWM period = 42.5 MHz / 42500 = 1000 Hz (1 kHz)
     * CCR1 = 21250  -> 50% duty cycle (21250 / 42500)
     */
    TIM3->PSC = 3U;
    TIM3->ARR = 42499U;
    TIM3->CCR1 = 21250U;

    /* Configure Channel 1 as output in PWM mode 1 with preload enabled */
    TIM3->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk);
    TIM3->CCMR1 |= (0x6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

