#include "stm32g4xx.h"

int main(void) {
    /* =========================================================================
     * 1. Enable peripheral clocks in RCC
     * ========================================================================= */
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOAEN;     /* Enable GPIOA clock */
    RCC->APB2ENR  |= RCC_APB2ENR_USART1EN;    /* Enable USART1 clock */
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;     /* Enable TIM3 clock */

    /* =========================================================================
     * 2. Configure GPIOA Alternate Functions
     *    - PA6:  AF2 (TIM3_CH1)
     *    - PA9:  AF7 (USART1_TX)
     *    - PA10: AF7 (USART1_RX)
     * ========================================================================= */
    /* Set Alternate Function mode (MODER = 10b) for PA6, PA9, and PA10 */
    GPIOA->MODER &= ~(GPIO_MODER_MODE6_Msk | GPIO_MODER_MODE9_Msk | GPIO_MODER_MODE10_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE6_Pos) |
                    (2U << GPIO_MODER_MODE9_Pos) |
                    (2U << GPIO_MODER_MODE10_Pos);

    /* Set High speed on TX pin (PA9) */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED9_Pos);

    /* AFR[0] (AFRL): Select AF2 for PA6 */
    GPIOA->AFR[0] &= ~(0xFU << GPIO_AFRL_AFSEL6_Pos);
    GPIOA->AFR[0] |= (2U << GPIO_AFRL_AFSEL6_Pos);

    /* AFR[1] (AFRH): Select AF7 for PA9 (TX) and PA10 (RX) */
    GPIOA->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL9_Pos) | (0xFU << GPIO_AFRH_AFSEL10_Pos));
    GPIOA->AFR[1] |= (7U << GPIO_AFRH_AFSEL9_Pos) | (7U << GPIO_AFRH_AFSEL10_Pos);

    /* =========================================================================
     * 3. Configure USART1 (Console)
     *    - 8 data bits (M0=0, M1=0), 1 stop bit (STOP=00b), no parity (PCE=0)
     *    - Oversampling by 16 (OVER8=0)
     *    - Baud rate: 115200 (BRR = 170 MHz / 115200 = 1476 = 0x5C4)
     *    - Note: BRR is written before USART1 is enabled (UE=1)
     * ========================================================================= */
    USART1->CR1 = 0U;                          /* Reset CR1: 8 data bits, no parity, OVER8=0 */
    USART1->CR2 = 0U;                          /* 1 stop bit */
    USART1->CR3 = 0U;                          /* Default CR3 */
    USART1->BRR = 1476U;                       /* Set baud rate divider before enabling UE */
    USART1->CR1 = USART_CR1_TE | USART_CR1_RE; /* Enable transmitter and receiver */
    USART1->CR1 |= USART_CR1_UE;               /* Enable USART1 peripheral */

    /* =========================================================================
     * 4. Configure TIM3 Channel 1 (1 kHz PWM, 50% duty cycle on PA6)
     *    - Kernel clock f_TIM3CLK = 170 MHz (PCLK1 = 170 MHz, APB1 prescaler = 1)
     *    - f_PWM = 170 MHz / ((PSC + 1) * (ARR + 1)) = 170 MHz / (4 * 42500) = 1 kHz
     *    - CCR1 = 42500 * 50% = 21250 (50% duty cycle)
