    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;

    /* 2. Configure PC4 and PC5 to Alternate Function mode (MODER[1:0] = 0b10) */
    GPIOC->MODER &= ~(GPIO_MODER_MODE4_Msk | GPIO_MODER_MODE5_Msk);
    GPIOC->MODER |= (GPIO_MODER_MODE4_1 | GPIO_MODER_MODE5_1);

    /* 3. Assign Alternate Function 7 (AF7: USART1_TX / USART1_RX) to PC4 and PC5 */
    GPIOC->AFR[0] &= ~((0xFU << GPIO_AFRL_AFSEL4_Pos) | (0xFU << GPIO_AFRL_AFSEL5_Pos));
    GPIOC->AFR[0] |= ((7U << GPIO_AFRL_AFSEL4_Pos) | (7U << GPIO_AFRL_AFSEL5_Pos));

    /* 4. Enable USART1 peripheral clock on APB2 */
    RCC->APB2ENR |= RCC_APB2ENR_USART1EN;

    /* 5. Set baud rate:
     * USART1 clock source defaults to PCLK2 = 170 MHz (RCC_CCIPR USART1SEL = 0b00).
     * With OVER8 = 0 (oversampling by 16):
     *   USARTDIV = f_CK / baud = 170000000 / 230400 ≈ 737.847
     * Rounding to nearest integer yields BRR = 738 (0x02E2).
     * Resulting baud rate: 170000000 / 738 ≈ 230352.3 baud (~0.02% error).
     * The baud-rate register is written prior to enabling the USART.
     */
    USART1->BRR = 738U;

    /* 6. Configure frame format and enable transceiver:
     * - CR1 M1=0, M0=0: 8 data bits (reset default)
     * - CR1 PCE=0: parity control disabled (reset default)
     * - CR1 OVER8=0: oversampling by 16 (reset default)
     * - CR2 STOP=00b: 1 stop bit (reset default)
     * Enable Transmitter (TE), Receiver (RE), and USART peripheral (UE).
     */
    USART1->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;
